module.exports = function(RED) {
    function ATConfigNode(n) {
        require('dotenv').config({
            path: './packages/node_modules/kumva-ivr/.env'
        })
        RED.nodes.createNode(this, n);

        this.name = n.name || "Africa's Talking";
        this.username = n.username || process.env.AT_USERNAME;
        this.apiKey = n.apiKey || process.env.AT_API_KEY;
        this.environment = n.environment || process.env.AT_ENVIRONMENT || 'sandbox';
        this.defaultCallerId = n.defaultCallerId || process.env.AT_CALLER_ID;
        this.defaultLanguage = n.defaultLanguage || 'en';
        this.defaultTimeout = parseInt(n.defaultTimeout) || 30;

        // Safe initialization
        if (!RED.kumva) {
            RED.kumva = {};
        }
        RED.kumva.atConfig = this;

        if (this.username && this.apiKey) {
            console.log(`✅ Kumva AT Config Loaded Successfully: ${this.username}`);
        } else {
            console.warn("⚠️  AT Credentials missing - set in config node or .env");
        }
    }

    RED.nodes.registerType("at-config", ATConfigNode);
};